// ---------------------------------------------------------------------------
// What a learner is told about each kind of component
// ---------------------------------------------------------------------------

type KnowledgeInput = Partial<Omit<ComponentKnowledge, "title" | "summary" | "materials">> & { title: string; summary: string; materials: string; install: string[]; connects: string };

