  site: { maintenance: ["Protect markers and the benchmark from plant and weather until the foundations are set out and checked"], qualityChecks: ["Checked against the survey and a second reference"], commonDefects: ["Markers knocked or moved", "Levels carried from a wrong reference"], safety: ["Keep people clear of excavation edges and moving plant"], quantityMethod: "Site area or length from the plot geometry." },
