const K = (category: CategoryId, input: KnowledgeInput): ComponentKnowledge => ({
  title: input.title,
  summary: input.summary,
  materials: input.materials,
  installation: input.install,
  connections: input.connects,
  maintenance: input.maintenance ?? DEFAULTS[category].maintenance,
  qualityChecks: input.qualityChecks ?? DEFAULTS[category].qualityChecks,
  commonDefects: input.commonDefects ?? DEFAULTS[category].commonDefects,
  safety: input.safety ?? DEFAULTS[category].safety,
  quantityMethod: input.quantityMethod ?? DEFAULTS[category].quantityMethod,
});

